use std::path::{Path,PathBuf};
pub fn is_preview_args(args:&[String])->bool{args.iter().any(|s|matches!(s.as_str(),"--preview"|"--live-preview"))}
pub fn storage_root(executable:&Path,preview:bool)->Result<PathBuf,String>{let parent=executable.parent().ok_or("Folder aplikasi tidak ditemukan.")?;Ok(parent.join(if preview{"preview-data"}else{"data"}))}
/// Note exports belong inside the portable data folder, never the process working directory.
pub fn exports_directory(root:&Path)->PathBuf{root.join("exports")}
#[cfg(test)]mod tests{use super::*;#[test]fn data_follows_the_executable_after_relocation(){for directory in ["C:/portable-one","D:/Folder With Spaces/mynotch"]{let root=Path::new(directory);assert_eq!(storage_root(&root.join("mynotch.exe"),false).unwrap(),root.join("data"));assert_eq!(storage_root(&root.join("mynotch.exe"),true).unwrap(),root.join("preview-data"));}}#[test]fn preview_args_detected_for_error_and_panic_logs(){assert!(is_preview_args(&["mynotch.exe".into(),"--preview".into()]));assert!(is_preview_args(&["mynotch.exe".into(),"--live-preview".into()]));assert!(!is_preview_args(&["mynotch.exe".into()]));}#[test]fn exports_are_rooted_in_the_portable_data_folder(){for directory in ["C:/portable-one","D:/Folder With Spaces/mynotch"]{let root=Path::new(directory).join("data");assert_eq!(exports_directory(&root),root.join("exports"));}}}
